import { FableChat } from "@/components/fable-ui/chat/fable-chat"

export default function FableChatPage() {
  return (
    <main className="min-h-screen bg-background">
      <FableChat />
    </main>
  )
}

import {
  convertToModelMessages,
  createUIMessageStream,
  createUIMessageStreamResponse,
  stepCountIs,
  streamText,
} from "ai"
import type { UIMessage } from "ai"

import {
  createFableAIModel,
  getConfigurationMessage,
  getFableAIConfigStatus,
  getProviderLabel,
} from "@/lib/fable-ui/quickstart/provider-config"
import { fableTools } from "@/lib/fable-ui/quickstart/tools"

type ChatRequestBody = {
  messages?: UIMessage[]
}

const noStoreHeaders = {
  "Cache-Control": "no-store, max-age=0",
  Pragma: "no-cache",
}

export async function POST(req: Request) {
  let body: ChatRequestBody

  try {
    body = (await req.json()) as ChatRequestBody
  } catch {
    return createTextOnlyResponse("Request error. The chat route received invalid JSON.")
  }

  const messages = body.messages ?? []
  const config = getFableAIConfigStatus()

  if (!config.ok) {
    return createTextOnlyResponse(
      getConfigurationMessage({
        missing: config.missing,
        error: config.error,
      }),
      messages,
    )
  }

  try {
    const result = streamText({
      model: createFableAIModel(config),
      system: [
        "You are a concise assistant in a production Fable UI quickstart chat.",
        `The configured provider is ${getProviderLabel(config.provider)} and the model is ${config.model}.`,
        "Use Fable UI tools only when the user's request is better answered with a trusted UI surface.",
        "Never call tools with generic placeholder data, fake metrics, or invented values.",
        "If exact values or context are missing, ask a short follow-up question or answer in text.",
        "When a metric is clearly available from the conversation, render it with show_metric.",
        "When useful next steps are requested, render them with show_next_actions.",
      ].join("\n"),
      messages: await convertToModelMessages(messages),
      tools: fableTools,
      toolChoice: "auto",
      stopWhen: stepCountIs(3),
    })

    return result.toUIMessageStreamResponse({
      headers: noStoreHeaders,
      onError: getPublicChatError,
    })
  } catch (error) {
    return createTextOnlyResponse(getPublicChatError(error), messages)
  }
}

export function GET() {
  return createTextOnlyResponse("POST chat messages to this route from `/fable-chat`.")
}

function createTextOnlyResponse(text: string, messages: UIMessage[] = []) {
  const stream = createUIMessageStream({
    originalMessages: messages,
    execute: ({ writer }) => {
      const id = "fable-chat-text"

      writer.write({ type: "text-start", id })
      writer.write({ type: "text-delta", id, delta: text })
      writer.write({ type: "text-end", id })
    },
  })

  return createUIMessageStreamResponse({ stream, headers: noStoreHeaders })
}

function getPublicChatError(error: unknown) {
  const message = error instanceof Error ? error.message : String(error || "")

  if (/api key|authentication|unauthorized|permission|forbidden|401|403/i.test(message)) {
    return "Provider authentication failed. Check `FABLE_AI_API_KEY` and confirm the key has access to the configured model."
  }

  if (/rate limit|quota|429/i.test(message)) {
    return "The configured AI provider is rate limited right now. Wait a moment, then try again."
  }

  if (/model|not found|unsupported|404/i.test(message)) {
    return "The configured model is unavailable for this provider or API key. Check `FABLE_AI_PROVIDER` and `FABLE_AI_MODEL`."
  }

  if (/timeout|network|fetch|econn|enotfound|socket/i.test(message)) {
    return "The chat route could not reach the AI provider. Check your network connection and provider status."
  }

  return "The chat route failed while asking the AI provider. Check the server logs for details."
}

"use client"

import { useMemo, useState } from "react"
import type { FormEvent, KeyboardEvent } from "react"
import { useChat } from "@ai-sdk/react"
import { DefaultChatTransport, type UIMessage } from "ai"
import { LoaderCircle, SendHorizontal } from "lucide-react"

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupTextarea,
} from "@/components/ui/input-group"
import {
  Marker,
  MarkerContent,
  MarkerIcon,
} from "@/components/ui/marker"
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/components/ui/message-scroller"
import { FableMessage } from "@/components/fable-ui/chat/fable-message"

function describeClientError(error: unknown) {
  const message = error instanceof Error ? error.message : String(error || "")

  if (/rate limit|quota|429/i.test(message)) {
    return "The AI provider is rate limited right now. Wait a moment and try again."
  }

  if (/api key|unauthorized|authentication|401|403/i.test(message)) {
    return "The AI provider rejected the request. Check `FABLE_AI_API_KEY` and model access."
  }

  if (/network|fetch|timeout|econn|enotfound/i.test(message)) {
    return "The chat request could not reach the server. Check your connection and try again."
  }

  return "The chat request failed. Please try again."
}

function ThinkingRow() {
  return (
    <Marker role="status" className="mx-auto w-full max-w-3xl px-4">
      <MarkerIcon>
        <LoaderCircle className="animate-spin" aria-hidden="true" />
      </MarkerIcon>
      <MarkerContent>
        <span className="inline-flex animate-pulse bg-gradient-to-r from-muted-foreground via-foreground to-muted-foreground bg-[length:200%_100%] bg-clip-text text-transparent">
          Thinking...
        </span>
      </MarkerContent>
    </Marker>
  )
}

export function FableChat() {
  const [input, setInput] = useState("")
  const [clientError, setClientError] = useState<string | null>(null)
  const transport = useMemo(() => new DefaultChatTransport({ api: "/api/fable-chat" }), [])
  const { messages, sendMessage, status, error, clearError } = useChat<UIMessage>({
    transport,
    messages: [],
    experimental_throttle: 80,
    onError: (nextError) => {
      setClientError(describeClientError(nextError))
    },
  })
  const isBusy = status === "submitted" || status === "streaming"
  const visibleError = clientError || (error ? describeClientError(error) : null)

  async function submitPrompt() {
    const text = input.trim()

    if (!text || isBusy) {
      return
    }

    setClientError(null)
    clearError()
    setInput("")

    try {
      await sendMessage({ text })
    } catch (nextError) {
      setInput(text)
      setClientError(describeClientError(nextError))
    }
  }

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    await submitPrompt()
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault()
      void submitPrompt()
    }
  }

  return (
    <MessageScrollerProvider
      autoScroll
      defaultScrollPosition="last-anchor"
      scrollPreviousItemPeek={64}
    >
      <section className="flex h-dvh min-h-0 flex-col overflow-hidden bg-background text-foreground">
        <header className="border-b px-4 py-3 sm:px-6">
          <div className="mx-auto flex max-w-3xl items-center justify-between gap-3">
            <div className="min-w-0">
              <h1 className="truncate text-sm font-semibold">Fable Chat</h1>
              <p className="truncate text-xs text-muted-foreground">
                Live AI responses with Fable UI tool rendering
              </p>
            </div>
          </div>
        </header>

        <MessageScroller className="min-h-0 flex-1">
          <MessageScrollerViewport>
            <MessageScrollerContent className="mx-auto flex min-h-full w-full max-w-3xl flex-col justify-end gap-4 px-4 py-6 sm:px-6">
              {messages.length === 0 && !isBusy ? (
                <div className="flex flex-1 items-center justify-center text-center text-muted-foreground">
                  <p className="max-w-md text-balance text-sm leading-6">
                    Ask a question. If a Fable UI surface is useful, the model can render it inline.
                  </p>
                </div>
              ) : null}

              {messages.map((message) => (
                <MessageScrollerItem
                  key={message.id}
                  messageId={message.id}
                  scrollAnchor={message.role === "user"}
                >
                  <FableMessage message={message} />
                </MessageScrollerItem>
              ))}

              {isBusy ? (
                <MessageScrollerItem messageId="assistant-thinking">
                  <ThinkingRow />
                </MessageScrollerItem>
              ) : null}
            </MessageScrollerContent>
          </MessageScrollerViewport>

          <MessageScrollerButton />
        </MessageScroller>

        <form onSubmit={handleSubmit} className="border-t bg-background/95 px-4 py-4 sm:px-6">
          <div className="mx-auto max-w-3xl">
            {visibleError ? (
              <div className="mb-3 rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
                {visibleError}
              </div>
            ) : null}

            <InputGroup className="min-h-24 rounded-3xl bg-card p-2 shadow-sm ring-1 ring-border">
              <InputGroupTextarea
                value={input}
                onChange={(event) => setInput(event.target.value)}
                onKeyDown={handleKeyDown}
                placeholder="Ask Fable Chat..."
                aria-label="Message"
                rows={1}
                disabled={isBusy}
                className="min-h-12 px-3 text-base"
              />
              <InputGroupAddon align="block-end" className="justify-end pt-2">
                <InputGroupButton
                  type="submit"
                  variant="default"
                  size="icon-sm"
                  disabled={isBusy || input.trim().length === 0}
                  aria-label="Send message"
                >
                  {isBusy ? (
                    <LoaderCircle className="animate-spin" aria-hidden="true" />
                  ) : (
                    <SendHorizontal aria-hidden="true" />
                  )}
                </InputGroupButton>
              </InputGroupAddon>
            </InputGroup>
          </div>
        </form>
      </section>
    </MessageScrollerProvider>
  )
}

import type { UIMessage } from "ai"
import ReactMarkdown from "react-markdown"
import remarkGfm from "remark-gfm"

import { Bubble, BubbleContent } from "@/components/ui/bubble"
import { Message, MessageContent } from "@/components/ui/message"
import { cn } from "@/lib/utils"
import { FableToolPart } from "@/components/fable-ui/chat/fable-tool-part"

function MarkdownResponse({ children }: { children: string }) {
  return (
    <div
      className={cn(
        "flex max-w-none flex-col gap-3 text-sm leading-7",
        "[&_a]:font-medium [&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4",
        "[&_blockquote]:border-l [&_blockquote]:pl-4 [&_blockquote]:text-muted-foreground",
        "[&_code]:rounded-md [&_code]:bg-muted [&_code]:px-1.5 [&_code]:py-0.5 [&_code]:font-mono [&_code]:text-xs",
        "[&_li]:ml-5 [&_ol]:list-decimal [&_pre]:overflow-x-auto [&_pre]:rounded-xl [&_pre]:bg-muted [&_pre]:p-4 [&_pre_code]:bg-transparent [&_pre_code]:p-0 [&_ul]:list-disc",
      )}
    >
      <ReactMarkdown remarkPlugins={[remarkGfm]}>{children}</ReactMarkdown>
    </div>
  )
}

export function FableMessage({ message }: { message: UIMessage }) {
  const isUser = message.role === "user"
  const align = isUser ? "end" : "start"

  return (
    <Message align={align}>
      <MessageContent className={cn("gap-3", isUser ? "items-end" : "items-stretch")}>
        {(message.parts ?? []).map((part, index) => {
          if (part.type === "text") {
            return (
              <Bubble
                key={`${message.id}-text-${index}`}
                align={align}
                variant={isUser ? "tinted" : "ghost"}
                className={isUser ? "w-fit max-w-[75%]" : "w-full max-w-full"}
              >
                <BubbleContent
                  className={cn(
                    "border-none",
                    isUser ? "rounded-tr-sm" : "w-full max-w-3xl px-0",
                  )}
                >
                  <MarkdownResponse>{part.text}</MarkdownResponse>
                </BubbleContent>
              </Bubble>
            )
          }

          if (part.type.startsWith("tool-")) {
            return (
              <div key={`${message.id}-tool-${index}`} className="w-full max-w-5xl">
                <FableToolPart part={part} />
              </div>
            )
          }

          return null
        })}
      </MessageContent>
    </Message>
  )
}

"use client"

import type { ToolPartLike } from "@/lib/fable-ui/core/definitions"
import { FableToolPart as RenderFableToolPart } from "@/lib/fable-ui/core/tool-renderer"
import { fableToolRegistry } from "@/lib/fable-ui/quickstart/tools"

export function FableToolPart({ part }: { part: ToolPartLike }) {
  return (
    <RenderFableToolPart
      part={part}
      registry={fableToolRegistry}
      handlers={{
        onSuggestedAction: (action) => {
          console.info("Suggested Fable action selected:", action)
        },
      }}
    />
  )
}

import { showMetric } from "@/lib/fable-ui/tools/show-metric-tool"
import { showNextActions } from "@/lib/fable-ui/tools/show-next-actions-tool"

export const fableToolRegistry = {
  show_metric: showMetric,
  show_next_actions: showNextActions,
}

export const fableTools = Object.fromEntries(
  Object.entries(fableToolRegistry).map(([name, def]) => [name, def.tool]),
)

import { createAnthropic } from "@ai-sdk/anthropic"
import { createDeepSeek } from "@ai-sdk/deepseek"
import { createGoogleGenerativeAI } from "@ai-sdk/google"
import { createMistral } from "@ai-sdk/mistral"
import { createOpenAI } from "@ai-sdk/openai"
import { createOpenRouter } from "@openrouter/ai-sdk-provider"
import type { LanguageModel } from "ai"

export type FableAIProvider =
  | "google"
  | "anthropic"
  | "openai"
  | "openrouter"
  | "mistral"
  | "deepseek"

const providerLabels: Record<FableAIProvider, string> = {
  google: "Google",
  anthropic: "Anthropic",
  openai: "OpenAI",
  openrouter: "OpenRouter",
  mistral: "Mistral",
  deepseek: "DeepSeek",
}

const providerIds = Object.keys(providerLabels) as FableAIProvider[]

export function getFableAIConfigStatus() {
  const provider = process.env.FABLE_AI_PROVIDER?.trim().toLowerCase()
  const model = process.env.FABLE_AI_MODEL?.trim()
  const apiKey = process.env.FABLE_AI_API_KEY?.trim()
  const missing = ([
    ["FABLE_AI_PROVIDER", provider],
    ["FABLE_AI_MODEL", model],
    ["FABLE_AI_API_KEY", apiKey],
  ] satisfies Array<[string, string | undefined]>)
    .filter(([, value]) => !value)
    .map(([name]) => name)

  if (missing.length > 0) {
    return { ok: false as const, missing }
  }

  if (!isFableAIProvider(provider)) {
    return {
      ok: false as const,
      missing: [],
      error: `FABLE_AI_PROVIDER must be one of: ${providerIds.join(", ")}.`,
    }
  }

  return {
    ok: true as const,
    provider,
    model: model!,
    apiKey: apiKey!,
  }
}

export function createFableAIModel(input: {
  provider: FableAIProvider
  model: string
  apiKey: string
}): LanguageModel {
  switch (input.provider) {
    case "anthropic":
      return createAnthropic({ apiKey: input.apiKey })(input.model)
    case "deepseek":
      return createDeepSeek({ apiKey: input.apiKey })(input.model)
    case "mistral":
      return createMistral({ apiKey: input.apiKey })(input.model)
    case "openai":
      return createOpenAI({ apiKey: input.apiKey })(input.model)
    case "openrouter":
      return createOpenRouter({ apiKey: input.apiKey })(input.model)
    case "google":
    default:
      return createGoogleGenerativeAI({ apiKey: input.apiKey })(input.model)
  }
}

export function getProviderLabel(provider: FableAIProvider) {
  return providerLabels[provider]
}

export function getConfigurationMessage(input: {
  missing?: string[]
  error?: string
}) {
  const missing = input.missing ?? []
  const missingText =
    missing.length > 0
      ? `\n\nMissing variables:\n${missing.map((name) => `- ${name}`).join("\n")}`
      : ""

  return [
    "Fable Chat is almost ready. Complete the AI provider configuration and restart your dev server.",
    input.error ? `\n\n${input.error}` : "",
    missingText,
    "\n\nAdd these to `.env.local`:",
    "```env",
    "FABLE_AI_PROVIDER=google",
    "FABLE_AI_MODEL=gemini-3-flash-preview",
    "FABLE_AI_API_KEY=your-provider-api-key",
    "```",
  ].join("\n")
}

function isFableAIProvider(value: unknown): value is FableAIProvider {
  return providerIds.includes(value as FableAIProvider)
}
